import React, { useState, useEffect, useRef } from 'react';
import PropTypes from 'prop-types';
import { CSSTransition, TransitionGroup } from 'react-transition-group';
import sr from '@utils/sr';
import { srConfig } from '@config';
import { FormattedIcon } from '@components/icons';
import { Heading } from '@styles';
import "react-responsive-carousel/lib/styles/carousel.min.css"; // requires a loader
import { useLocation } from '@reach/router';
import 'bootstrap/dist/css/bootstrap.min.css';

import {
  StyledContainer,
  StyledProject,
  StyledContent,
  StyledLabel,
  StyledProjectName,
  StyledDescription,
  StyledTechList,
  StyledLinkWrapper,
  StyledFeaturedImg,
  StyledList,
  StyledImgContainer,
  StyledListItem,
  StyledListLink,
} from '../styles/featured-style';
import useCurrentTag from '../helpers/tag-helper';

import Carousel from 'react-bootstrap/Carousel';

const Featured = ({ data }) => {

  const featuredProjects = data.filter(({ node }) => node);

  const winLocation = useLocation();

  const projectCategoryToProjectDetails = {};
  let allTags = new Set(["All"]);

  projectCategoryToProjectDetails["All"] = [];
  featuredProjects.forEach(({ node }) => {
    const { tags } = node.frontmatter;
    projectCategoryToProjectDetails["All"].push({ node });

    tags?.forEach((tag) => {
      allTags.add(tag);
      if (!projectCategoryToProjectDetails[tag]) projectCategoryToProjectDetails[tag] = [];
      projectCategoryToProjectDetails[tag].push({ node });
    });
  });

  allTags = Array.from(allTags);

  const moreThanOneTag = (jsx) => allTags.length > 1 ? jsx : null;

  const currentTag = useCurrentTag(); // Use the custom hook here
  const selectedProjects = projectCategoryToProjectDetails[currentTag];

  const revealTitle = useRef(null);
  const revealProjects = useRef([]);
  useEffect(() => {
    sr.reveal(revealTitle.current, srConfig());
    revealProjects.current.forEach((ref, i) => sr.reveal(ref, srConfig(i * 100)));
  }, []);

  return (
    <StyledContainer id="projects">
      <Heading ref={revealTitle}>Some Things I&apos;ve Built</Heading>

      {
        moreThanOneTag(
          <StyledList>
            {allTags.map((tag, index) => (
              <StyledListLink key={index} to={`${winLocation.pathname}#projects?tag=${tag}`} >
                {tag}
              </StyledListLink>
            ))}
          </StyledList>
        )}

      <div>
        {selectedProjects &&
          selectedProjects.map(({ node }, i) => {
            const { frontmatter, html } = node;
            const { external, title, tech, github, imageCarousel, gifCarousel, drive, youtube } = frontmatter;

            const hasImages = (imageCarousel && imageCarousel.length > 0) || (gifCarousel && gifCarousel.length > 0);

            return (
              <StyledProject key={i} className={!hasImages ? 'no-image' : ''} ref={el => (revealProjects.current[i] = el)}>
                <StyledContent>
                  <StyledLabel>Featured Project</StyledLabel>
                  <StyledProjectName>
                    {external ? (
                      <a href={external} target="_blank" rel="nofollow noopener noreferrer">
                        {title}
                      </a>
                    ) : (
                      title
                    )}
                  </StyledProjectName>
                  <StyledDescription dangerouslySetInnerHTML={{ __html: html }} />
                  {tech && (
                    <StyledTechList>
                      {tech.map((item, i) => (
                        <li key={i}>{item}</li>
                      ))}
                    </StyledTechList>
                  )}
                  <StyledLinkWrapper>
                    {github && (
                      <a href={github} target="_blank" rel="nofollow noopener noreferrer">
                        <FormattedIcon name="GitHub" />
                      </a>
                    )}
                    {drive && (
                      <a href={drive} target="_blank" rel="nofollow noopener noreferrer">
                        <FormattedIcon name="Drive" />
                      </a>
                    )}
                    {external && (
                      <a href={external} target="_blank" rel="nofollow noopener noreferrer">
                        <FormattedIcon name="External" />
                      </a>
                    )}
                    {youtube && (
                      <a href={youtube} target="_blank" rel="nofollow noopener noreferrer">
                        <FormattedIcon name="Youtube" />
                      </a>
                    )}
                  </StyledLinkWrapper>
                </StyledContent>

                {/* <StyledImgContainer href={external || github || '#'} target="_blank" rel="nofollow noopener noreferrer">
                  <StyledFeaturedImg image={cover && cover.childImageSharp.gatsbyImageData} alt={title} />
                  {covergif && <img src={covergif} alt="img" />}
                </StyledImgContainer> */}

                <StyledImgContainer>
                  <Carousel>
                    {imageCarousel && imageCarousel.map((image, idx) => (
                      image && image.childImageSharp ? (
                        <Carousel.Item key={idx}>
                          <StyledFeaturedImg image={image.childImageSharp.gatsbyImageData} alt={`Cover ${idx + 1}`} />
                        </Carousel.Item>
                      ) : null
                    ))}

                    {gifCarousel && gifCarousel.map((gif, idx) => (
                      gif ? (
                        <Carousel.Item>
                          <img src={gif} alt="img" />
                        </Carousel.Item>
                      ) : null
                    ))}

                  </Carousel>
                </StyledImgContainer>

              </StyledProject>
            );
          })}
      </div>
    </StyledContainer>
  );
};

Featured.propTypes = {
  data: PropTypes.array.isRequired,
};

export default Featured;