
import styled from 'styled-components';
import { GatsbyImage } from "gatsby-plugin-image";
import { Link } from 'gatsby';
import { theme, mixins, media, Section } from '@styles';

const { colors, fontSizes, fonts } = theme;

export const StyledContainer = styled(Section)`
  ${mixins.flexCenter};
  flex-direction: column;
  align-items: flex-start;
`;

export const StyledContent = styled.div`
  position: relative;
  grid-column: 1 / 7;
  grid-row: 1 / -1;
  text-align: justify;
  
  ${media.thone`
    grid-column: 1 / -1;
    padding: 40px 40px 30px;
    z-index: 5;
  `};

  ${media.phablet`padding: 30px 25px 20px;`};
`;

export const StyledLabel = styled.h4`
  font-size: ${fontSizes.smish};
  font-weight: normal;
  color: ${colors.green};
  font-family: ${fonts.SFMono};
  margin-top: 10px;
  padding-top: 0;
`;

export const StyledProjectName = styled.h5`
  font-size: 28px;
  position: relative;
  z-index: 2;
  margin: 0 0 20px;
  color: ${colors.lightestSlate};
  
  ${media.tablet`font-size: 24px;`};
  
  ${media.thone`color: ${colors.white};`};
  
  a {
    ${media.tablet`display: block;`};
  }
`;

export const StyledDescription = styled.div`
  ${mixins.boxShadow};
  position: relative;
  z-index: 2;
  padding: 25px;
  background-color: ${colors.lightNavy};
  color: ${colors.lightSlate};
  font-size: ${fontSizes.lg};
  border-radius: ${theme.borderRadius};
  
  ${media.thone`
    background-color: transparent;
    padding: 20px 0;
    box-shadow: none;
    &:hover {
      box-shadow: none;
    }
  `};
  
  p {
    margin: 0;
  }
  
  a {
    ${mixins.inlineLink};
  }
`;

export const StyledTechList = styled.ul`
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  padding: 0;
  margin: 25px 0 10px;
  list-style: none;

  li {
    font-family: ${fonts.SFMono};
    font-size: ${fontSizes.smish};
    color: ${colors.green};
    margin-right: ${theme.margin};
    margin-bottom: 7px;
    white-space: nowrap;
    &:last-of-type {
      margin-right: 0;
    }
    
    ${media.thone`
      color: ${colors.green};
      margin-right: 10px;
    `};
  }
`;

export const StyledLinkWrapper = styled.div`
  display: flex;
  align-items: center;
  position: relative;
  margin-top: 10px;
  margin-left: -10px;
  color: ${colors.lightestSlate};
  a {
    padding: 10px;
    svg {
      width: 22px;
      height: 22px;
    }
  }
`;

export const StyledFeaturedImg = styled(GatsbyImage)`
  width: 100%;
  max-width: 100%;
  vertical-align: middle;
  border-radius: ${theme.borderRadius};
  position: relative;
  
  
  ${media.tablet`
    object-fit: cover;
    width: auto;
    height: 100%;
  `};
`;

export const StyledImgContainer = styled.div`
  ${mixins.boxShadow};
  grid-column: 7 / -1;
  grid-row: 1 / -1;
  position: relative;
  z-index: 1;
  border-radius: ${theme.radius + 1}px;
  transition: ${theme.transition};

  ${media.tablet`height: 100%;`};

  ${media.thone`
    grid-column: 1 / -1;
  `};
`;

export const StyledProject = styled.div`
  display: grid;
  grid-gap: 10px;
  grid-template-columns: repeat(12, 1fr);
  align-items: center;
  margin-bottom: 100px;

  ${media.thone`
    margin-bottom: 70px;
  `};

  &:last-of-type {
    margin-bottom: 0;
  }

  &:nth-of-type(odd) {
    ${StyledContent} {
      grid-column: 7 / -1;
      text-align: justify;
      
      ${media.thone`
        grid-column: 1 / -1;
        padding: 40px 40px 30px;
      `};
      
      ${media.phablet`padding: 30px 25px 20px;`};
    }

    ${StyledTechList} {
      justify-content: flex-end;
      li {
        margin-left: ${theme.margin};
        margin-right: 0;
      }
    }
    
    ${StyledLinkWrapper} {
      justify-content: flex-end;
      margin-left: 0;
      margin-right: -10px;
    }

    ${StyledImgContainer} {
      grid-column: 1 / 7;
      
      ${media.tablet`height: 100%;`};
      
      ${media.thone`
        grid-column: 1 / -1;
      `};
    }
  }

  &.no-image ${StyledContent} {
    grid-column: 2 / -3; /* Make StyledContent occupy all columns */
  }

  &.no-image ${StyledImgContainer} {
    display: none; /* Hide the image container if no images are available */
  }
`;

export const StyledList = styled.ol`
  ${mixins.flexBetween};
  padding: 0;
  margin: 0;
  list-style: none;
`;

export const StyledListItem = styled.li`
  margin: 0 10px;
  position: relative;
  font-size: ${fontSizes.smish};
  counter-increment: item 1;
  
  &:before {
    content: '0' counter(item) '.';
    text-align: right;
    color: ${colors.green};
    font-size: ${fontSizes.xs};
  }
`;

export const StyledListLink = styled(Link)`
  padding: 12px 10px;
`;